-- Transitional safety net: legacy UI writes that have not yet been upgraded may omit tenant_id.
-- We infer it only when the authenticated user has exactly one active tenant. Ambiguous writes fail closed.
create or replace function public.infer_single_tenant_for_user() returns uuid language plpgsql stable security definer set search_path=public as $$declare ids uuid[];begin select array_agg(tenant_id order by tenant_id) into ids from public.tenant_memberships where user_id=auth.uid() and active=true;if coalesce(array_length(ids,1),0)=1 then return ids[1];end if;if public.is_platform_staff(array['platform_owner']) and coalesce(array_length(ids,1),0)=0 then return '00000000-0000-4000-8000-000000000001'::uuid;end if;raise exception 'tenant_context_required';end$$;
create or replace function public.assign_missing_tenant() returns trigger language plpgsql security definer set search_path=public as $$begin if new.tenant_id is null then new.tenant_id:=public.infer_single_tenant_for_user();end if;if not public.can_access_tenant(new.tenant_id,null) then raise exception 'tenant_access_denied';end if;return new;end$$;
do $$declare t text;begin foreach t in array array['pages','page_blocks','media_assets','projects','leads','revisions'] loop execute format('drop trigger if exists assign_missing_tenant on public.%I',t);execute format('create trigger assign_missing_tenant before insert on public.%I for each row execute function public.assign_missing_tenant()',t);end loop;end$$;
